-- Marketing analytics wiki section (top-level sibling of "Data modeling").
-- Idempotent: pages upsert by slug; parent wiring and wikilinks are join-based and
-- safe to re-run. Cross-section wikilinks resolve only once the target pages exist,
-- so re-run all five domain seeds after the first pass to wire cross-links.
-- Mirrors what was seeded to the live DB via the Supabase MCP (2026-06).

insert into pages (title, slug, kind, content, visibility) values ('Marketing analytics', 'marketing-analytics', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing analytics is the measurement of how marketing creates and influences revenue, across a long and messy B2B buying journey. Demand generation, acquisition, attribution, channel performance, and the funnel from a first anonymous visit to a closed deal."}]},{"type":"paragraph","content":[{"type":"text","text":"Two structural facts make it different from the consumer version. B2B deals involve a buying group of six to ten people, not one shopper, and the journey is long, low-volume, and high-value. A large slice of the influence happens in the dark funnel, the Slack groups and podcasts and peer chats no pixel ever sees."}]},{"type":"paragraph","content":[{"type":"text","text":"It sits next to "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Product analytics"}},{"type":"text","text":" as a domain. The theory is funnels, attribution, and acquisition economics. The practice is the unglamorous data work that makes attribution trustworthy: tracking hygiene, identity resolution, and one set of definitions."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Theory"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The funnel — ","marks":[{"type":"bold"}]},{"type":"text","text":"visitor to lead to MQL to SQL to opportunity, and the economics of moving people through it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution — ","marks":[{"type":"bold"}]},{"type":"text","text":"the contested core: which touches get credit, and the shift away from last-touch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Acquisition — ","marks":[{"type":"bold"}]},{"type":"text","text":"channels, sourced versus influenced pipeline, the dark funnel, and product-led acquisition."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Practice"}]},{"type":"paragraph","content":[{"type":"text","text":"UTM hygiene, identity resolution, attribution modeling in dbt, the MQL dispute, and the marketing data stack."}]},{"type":"paragraph","content":[{"type":"text","text":"The honest summary: most marketing-attribution failures are governance problems, not tooling problems. Garbage UTMs make garbage attribution no matter how clever the model."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The acquisition funnel"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Marketing analytics practice"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Marketing voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The acquisition funnel', 'the-acquisition-funnel', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The classic B2B funnel is a sequence of stages with a definition at each boundary: visitor, lead, MQL, SQL, opportunity, closed-won. The value is not the diagram, it's forcing an explicit definition of what qualifies at each step."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MQL — ","marks":[{"type":"bold"}]},{"type":"text","text":"marketing qualified lead. An engagement or fit signal, not yet sales-ready. Where the marketing-sales argument starts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SQL — ","marks":[{"type":"bold"}]},{"type":"text","text":"sales qualified lead. Validated by sales for budget, authority, need, timing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opportunity — ","marks":[{"type":"bold"}]},{"type":"text","text":"an SQL with an active deal and a forecast attached. The handoff to "}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Conversion benchmarks float around (visitor to lead near 2%, MQL to SQL near 13%) but they vary so much by source and segment that the average is almost useless. The source of the lead predicts conversion better than any stage rate: an event lead and a cold paid-list lead are not the same animal."}]},{"type":"paragraph","content":[{"type":"text","text":"Modeled well, the funnel is a "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" question: one row per person per stage transition, with the timestamp and the source. Get that grain right and every conversion rate falls out cleanly. The sales side picks it up at "},{"type":"wikilink","attrs":{"title":"The pipeline and stages"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Attribution models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Unit economics of acquisition"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The pipeline and stages"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Attribution models', 'attribution-models', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution is the act of assigning credit for a conversion across the touchpoints that led to it. It's the central, contested problem of B2B marketing because deals involve many people over many months, and no model is right, only more or less useful."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First-touch — ","marks":[{"type":"bold"}]},{"type":"text","text":"100% to the first interaction. Measures demand creation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Last-touch — ","marks":[{"type":"bold"}]},{"type":"text","text":"100% to the final interaction. Measures demand capture. Still the most common despite its known blind spot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Linear and time-decay — ","marks":[{"type":"bold"}]},{"type":"text","text":"spread credit evenly, or weight it toward touches nearer the conversion."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"W-shaped — ","marks":[{"type":"bold"}]},{"type":"text","text":"the common B2B choice: heavy credit to first touch, lead creation, and opportunity creation, the rest spread thin."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data-driven — ","marks":[{"type":"bold"}]},{"type":"text","text":"machine learning weights touches by measured influence. Needs high conversion volume, which most enterprise B2B doesn't have."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The right answer is usually to pick a model that matches the question and be consistent, then encode it once so marketing and sales can't report different credit from the same data. That encoding is "},{"type":"wikilink","attrs":{"title":"Attribution modeling in dbt"}},{"type":"text","text":". The bigger shift in how to measure is "},{"type":"wikilink","attrs":{"title":"Beyond last-touch (MMM and incrementality)"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Beyond last-touch (MMM and incrementality)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Attribution modeling in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The acquisition funnel"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Beyond last-touch (MMM and incrementality)', 'beyond-last-touch', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Confidence in user-level multi-touch attribution is eroding, and for good reasons: third-party cookies are going away, mobile privacy blocks tracking, and consent gaps leave holes in the journey. The field's answer is to stop relying on one method."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Method stacking"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-touch attribution (MTA) — ","marks":[{"type":"bold"}]},{"type":"text","text":"granular, touch-level, good for day-to-day optimization. The thing that's getting less reliable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing mix modeling (MMM) — ","marks":[{"type":"bold"}]},{"type":"text","text":"aggregate and privacy-safe, regresses outcomes on spend across channels. Coming back into fashion precisely because it needs no tracking."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Incrementality testing — ","marks":[{"type":"bold"}]},{"type":"text","text":"holdout and geo experiments that measure causal lift. The only one that actually proves an ad worked rather than coincided with a sale."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The mature stance is to triangulate: MTA for the steering wheel, MMM for the budget split, incrementality to check both against reality. This is the marketing cousin of "},{"type":"wikilink","attrs":{"title":"Experimentation"}},{"type":"text","text":": observational attribution shows correlation, a holdout shows cause. Treat any single attribution number as one estimate, not the truth."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Attribution models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Experimentation"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Channels and campaign performance"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Channels and campaign performance', 'channels-and-campaign-performance', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Channel and campaign analysis is the bread and butter: spend, cost per lead, cost per opportunity, and return by channel and campaign. The goal is to move budget toward what works, which sounds obvious and is hard because the measurement is exactly the contested attribution problem."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paid — ","marks":[{"type":"bold"}]},{"type":"text","text":"search, social, display. Easy to measure click-to-lead, hard to measure true contribution past the click."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Owned — ","marks":[{"type":"bold"}]},{"type":"text","text":"web, email, content, SEO. Cheap per touch, slow to attribute, often undercounted by last-touch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Earned and community — ","marks":[{"type":"bold"}]},{"type":"text","text":"referral, word of mouth, the dark funnel. The highest-converting and the least trackable."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The modeling job is a clean spend table at one row per campaign per day, with consistent campaign attributes, joined to the touch and opportunity data. The recurring trap is comparing channels on a single attribution model that structurally favors one of them. LinkedIn is the dominant paid B2B channel; PPC tends to show the weakest funnel. Cost per opportunity beats cost per lead, because leads are cheap and opportunities are real."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Attribution models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Unit economics of acquisition"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The marketing data stack"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Unit economics of acquisition', 'unit-economics-of-acquisition', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The acquisition view of unit economics: what does it cost to win a customer, and is it worth it. The numbers are the same canon as "},{"type":"wikilink","attrs":{"title":"Unit economics (CAC, LTV, payback)"}},{"type":"text","text":" in finance, looked at through the marketing lens."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CAC — ","marks":[{"type":"bold"}]},{"type":"text","text":"sales and marketing cost divided by new customers. Blended hides the unprofitable channel; segment it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CAC payback — ","marks":[{"type":"bold"}]},{"type":"text","text":"months to earn the cost back. The number a cash-constrained business should watch above the LTV:CAC ratio."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LTV:CAC — ","marks":[{"type":"bold"}]},{"type":"text","text":"the folk 3:1 benchmark, with the same caveat: it came from mature public SaaS and gets misapplied to early stage."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Marketing owns the input side of these: the spend, the channel mix, the conversion rates. Finance owns the definition and the reconciliation. The friction between the two is healthy when both read the same numbers and destructive when they don't, which is the whole argument for a shared semantic layer."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Unit economics (CAC, LTV, payback)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Channels and campaign performance"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Marketing-sourced vs influenced pipeline"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Marketing-sourced vs influenced pipeline', 'sourced-vs-influenced-pipeline', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two ways to count marketing's contribution to pipeline, and the difference is a constant source of argument."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourced — ","marks":[{"type":"bold"}]},{"type":"text","text":"opportunities where marketing originated the first touch or the lead. A narrow, defensible number."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Influenced — ","marks":[{"type":"bold"}]},{"type":"text","text":"opportunities marketing touched at any point. A broad number, usually much larger, and easy to inflate."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Both are legitimate; they answer different questions. Sourced asks what marketing started. Influenced asks where marketing helped. The mistake is reporting influenced as if it were sourced, or letting the definition drift so this quarter's number isn't comparable to last quarter's."}]},{"type":"paragraph","content":[{"type":"text","text":"In the model this is computed at the lead-to-opportunity join: sourced is the first touch before opportunity creation, influenced is any marketing touch on the opportunity's contacts. Encode both definitions once in dbt and reuse them, or marketing and sales will pull different numbers from the same warehouse and spend the QBR arguing about which is right. This is the seam into "},{"type":"wikilink","attrs":{"title":"The pipeline and stages"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The acquisition funnel"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The pipeline and stages"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Attribution modeling in dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The dark funnel', 'the-dark-funnel', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dark funnel is everything that influences a buyer but leaves no trackable trace: the Slack community, the podcast, the peer who recommended you, the review site read in an incognito tab. It's a large part of how B2B buying actually happens, and attribution software is structurally blind to it."}]},{"type":"paragraph","content":[{"type":"text","text":"The practical response is to stop pretending the pixel sees everything and add a human signal. Self-reported attribution, the \"how did you hear about us\" field on the form plus periodic microsurveys, is the most-cited complement. It's noisy and it's qualitative, and it catches the influence your tracking misses entirely."}]},{"type":"paragraph","content":[{"type":"text","text":"For analytics engineers this is a humility lesson worth modeling explicitly: capture self-reported source as its own field, keep it next to the tracked attribution, and never let a clean-looking attributed number masquerade as the whole truth. The map is not the territory, and the tracked funnel is not the buying journey."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Attribution models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Beyond last-touch (MMM and incrementality)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Marketing voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Product-led acquisition', 'product-led-acquisition', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In product-led growth the product is the acquisition channel. The funnel becomes acquisition, activation, revenue, retention, and the key seam is signup to activation to a sales handoff. Marketing analytics owns getting people to sign up and activate; "},{"type":"wikilink","attrs":{"title":"Product analytics"}},{"type":"text","text":" owns what happens inside the product after."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Trials and freemium"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opt-in trial — ","marks":[{"type":"bold"}]},{"type":"text","text":"no card required, low friction, lower intent. Converts in the low teens by most directional benchmarks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opt-out trial — ","marks":[{"type":"bold"}]},{"type":"text","text":"card required, auto-converts unless cancelled. Converts three to four times higher but captures far less top of funnel."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Freemium — ","marks":[{"type":"bold"}]},{"type":"text","text":"a permanent free tier, a packaging decision not a conversion tactic. Free to paid often sits low single digits."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse trial — ","marks":[{"type":"bold"}]},{"type":"text","text":"everyone starts with full premium, then downgrades to free at trial end rather than losing access. A blend of the two."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The thing that actually drives conversion is not the paywall, it's activation and time to value, which means the trial is a product-analytics problem wearing a marketing hat. A product-qualified lead, a user whose in-product behavior signals intent, is the handoff artifact, defined as a warehouse-computed threshold and routed to sales. The billing mechanics of trials live in "},{"type":"wikilink","attrs":{"title":"Subscription and billing mechanics"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Metrics that matter"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Subscription and billing mechanics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The acquisition funnel"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Marketing voices and canon', 'marketing-voices-and-canon', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"B2B marketing analytics has fewer canonical books than data modeling. The canon is mostly practitioner blogs, podcasts, communities, and vendor research. Be honest about that: there's no Kimball-equivalent here."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The loud voices"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chris Walker (Refine Labs) — ","marks":[{"type":"bold"}]},{"type":"text","text":"the dark funnel, demand creation versus capture, and self-reported attribution."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dave Gerhardt (DGMG) — ","marks":[{"type":"bold"}]},{"type":"text","text":"B2B brand and demand, and one of the bigger communities."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Avinash Kaushik — ","marks":[{"type":"bold"}]},{"type":"text","text":"the older web-analytics canon, Web Analytics 2.0, still the measurement-principles foundation."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Vendor research used as reference"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"6sense — ","marks":[{"type":"bold"}]},{"type":"text","text":"the Science of B2B attribution and buying-group benchmarks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gartner — ","marks":[{"type":"bold"}]},{"type":"text","text":"the buying-group research everyone cites."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dreamdata, HockeyStack, Factors — ","marks":[{"type":"bold"}]},{"type":"text","text":"warehouse-first attribution vendors who publish useful benchmark and methodology writing."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Communities"}]},{"type":"paragraph","content":[{"type":"text","text":"Pavilion, Peak Community, DGMG, RevGenius, and MeasureCamp for the implementation-focused crowd. The dark-funnel engagement happens here, which is the joke and the point."}]},{"type":"paragraph","content":[{"type":"text","text":"Every conversion and CAC benchmark in this section is vendor or agency data with wide variance. Treat the numbers as directional.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Marketing analytics practice', 'marketing-analytics-practice', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution theory is the easy half. This hub is the data work that decides whether any of it is trustworthy: clean tracking, resolved identity, and definitions that live in one place."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"UTM and tracking hygiene, the single biggest data-quality lever."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identity resolution, stitching anonymous visitors to people to accounts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution modeling in dbt and the MQL definition dispute."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The marketing data stack and how it lands in the warehouse."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Marketing analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Attribution modeling in dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('UTM and tracking hygiene', 'utm-and-tracking-hygiene', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UTMs are the source, medium, and campaign tags on inbound links, and they are the single biggest data-quality lever in marketing attribution. Inconsistent UTMs produce inconsistent attribution, full stop. No model fixes a dirty source column."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What good looks like"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A governed taxonomy — ","marks":[{"type":"bold"}]},{"type":"text","text":"one documented convention for source, medium, and campaign, with a fixed vocabulary, not free text."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enforcement at link creation — ","marks":[{"type":"bold"}]},{"type":"text","text":"a builder tool or a required template, so the convention is the path of least resistance, not a thing people remember."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CRM hygiene alongside — ","marks":[{"type":"bold"}]},{"type":"text","text":"deduplicated contacts and consistent lead-source fields, so the offline side matches the online side."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" applied to the top of the funnel. Validate UTMs against the allowed vocabulary, alert on unmapped values, and treat an unmapped campaign as a defect. The discipline is boring and it's the difference between attribution you can defend and attribution you quietly stop trusting."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Identity resolution for marketing"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The marketing data stack"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Identity resolution for marketing', 'identity-resolution-for-marketing', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The hard part of marketing modeling is the same as product analytics: most activity is anonymous, and you have to stitch it to a known person, then to an account. The quality of that stitch caps the quality of all attribution downstream."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The chain"}]},{"type":"paragraph","content":[{"type":"text","text":"Anonymous visitor or session, then person, lead, or contact, then account. B2B needs both the person grain and the account grain, because credit usually has to roll up from an individual touch to the buying group."}]},{"type":"paragraph","content":[{"type":"text","text":"CDPs emit identify calls that link an anonymous id to a user id; dbt or the CDP then ties contacts to accounts. This is the same identity-resolution problem described in "},{"type":"wikilink","attrs":{"title":"Identity and sessions"}},{"type":"text","text":", just pointed at the marketing journey instead of in-product behavior. Use stable database ids over emails for the same reason it matters there: emails change, ids shouldn't."}]},{"type":"paragraph","content":[{"type":"text","text":"Model it as an explicit "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" problem: a person dimension, an account dimension, and a resolved touch table that carries both keys. Everything else, sourced versus influenced, channel ROI, the funnel, joins through it."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Identity and sessions"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Attribution modeling in dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Attribution modeling in dbt', 'attribution-modeling-in-dbt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution is where marketing analytics becomes a dimensional-modeling problem. The layered build, roughly:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stage — ","marks":[{"type":"bold"}]},{"type":"text","text":"raw sources: web events, CRM deals and contacts, ad spend per platform."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Spend model — ","marks":[{"type":"bold"}]},{"type":"text","text":"one row per campaign per day, with campaign attributes, for cost and ROI."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Touches model — ","marks":[{"type":"bold"}]},{"type":"text","text":"a unified, deduplicated touch table, one row per person per touch, with timestamp, channel, campaign, and resolved identity."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Journey — ","marks":[{"type":"bold"}]},{"type":"text","text":"order the touches per person and account, tag first touch, lead creation, opportunity creation, last touch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Allocation — ","marks":[{"type":"bold"}]},{"type":"text","text":"apply the model weights as window functions; data-driven models need an external step joined back in."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marts — ","marks":[{"type":"bold"}]},{"type":"text","text":"credited revenue per touch and channel, plus conformed campaign, account, and lead dimensions."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The point of doing it in dbt rather than in the attribution tool is governance: sourced versus influenced, the funnel stages, and the credit rules are defined once and reused. Open examples exist (the Snowplow attribution package, community dbt models). This is the same move as everywhere else in taro: define the logic once, in code, so two surfaces can't disagree."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Attribution models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Identity resolution for marketing"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The MQL dispute', 'the-mql-dispute', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The MQL definition is the perennial marketing-sales fight. Marketing counts a whitepaper download as a qualified lead; sales wants budget and authority before they'll touch it. Both are reasonable, and the gap between them wastes pipeline and trust."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The fixes people actually use"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One co-authored definition — ","marks":[{"type":"bold"}]},{"type":"text","text":"marketing and sales write the MQL criteria together, with explicit thresholds and a follow-up SLA. Boring, effective."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kill the MQL — ","marks":[{"type":"bold"}]},{"type":"text","text":"a growing camp replaces it with SQLs, pipeline, and CAC payback as the shared KPIs. An opinion, not consensus, but a serious one."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For analytics this is a definitions problem in disguise, and the same answer applies: whatever the org decides an MQL is, encode it once and version it, so the number means the same thing in every report. The dispute is really about who owns the definition, which is why it never gets settled in a tool, only in a conversation. Most of these alignment failures are governance, not software."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The acquisition funnel"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Marketing-sourced vs influenced pipeline"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"RevOps as a function"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The marketing data stack', 'the-marketing-data-stack', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The systems that feed marketing analytics, sorted by what they actually do:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Web and product — ","marks":[{"type":"bold"}]},{"type":"text","text":"GA4 and product-analytics tools for behavior; GA4's default attribution is data-driven and ties to BigQuery."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CRM and automation — ","marks":[{"type":"bold"}]},{"type":"text","text":"HubSpot, Salesforce, Marketo, the system of record for leads, contacts, and deals."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution platforms — ","marks":[{"type":"bold"}]},{"type":"text","text":"Bizible / Marketo Measure (legacy enterprise), Dreamdata and HockeyStack (warehouse-first), Factors and 6sense (ABM and intent)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CDP — ","marks":[{"type":"bold"}]},{"type":"text","text":"Segment, RudderStack for identity and event collection, increasingly composable and warehouse-native."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ad platforms — ","marks":[{"type":"bold"}]},{"type":"text","text":"LinkedIn (the dominant B2B channel), Google, Meta."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The path into the warehouse is the standard one: connectors (Fivetran, Airbyte) extract and load into Snowflake or BigQuery, dbt transforms into conformed marketing models, BI and reverse-ETL activate it back to the ad and CRM tools. The clear direction is warehouse-native and composable, the same trend described in "},{"type":"wikilink","attrs":{"title":"The platform landscape"}},{"type":"text","text":" for product analytics. Own the data in a warehouse you control, not a SaaS silo you rent."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The platform landscape"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Attribution modeling in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Materialization strategies"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
update pages c set parent_id = pa.id from pages pa where pa.slug = 'marketing-analytics' and c.slug in ('the-acquisition-funnel','attribution-models','beyond-last-touch','channels-and-campaign-performance','unit-economics-of-acquisition','sourced-vs-influenced-pipeline','the-dark-funnel','product-led-acquisition','marketing-voices-and-canon','marketing-analytics-practice');
